1	import { db } from "@/lib/db";
2	import { getCurrentUser } from "@/lib/auth";
3	import { runAgent, normalizePath, type FileMap } from "@/lib/agent";
4	import { buildSite, BuildError } from "@/lib/build-site";
5	import {
6	  chargeForBuild,
7	  costMicros,
8	  getBalance,
9	  getSpendCapStatus,
10	  settleBuild,
11	  sumUsage,
12	  type Usage,
13	} from "@/lib/credits";
14	import { checkGenerateRateLimit } from "@/lib/rate-limit";
15	import { track, EVENTS } from "@/lib/events";
16	import { classifyFollowUp } from "@/lib/feedback-intent";
17	import { FLAGS, isEnabled } from "@/lib/flags";
18	import { brandPromptFragment, parseStoredBrandKit } from "@/lib/brand-kit";
19	
20	export const dynamic = "force-dynamic";
21	export const maxDuration = 300;
22	
23	function sse(event: unknown) {
24	  return `data: ${JSON.stringify(event)}\n\n`;
25	}
26	
27	// A build that fails to compile even after one repair attempt gives up — this
28	// bounds the worst case to ~2x the cost of a normal generation, not unbounded.
29	const MAX_BUILD_ATTEMPTS = 2;
30	
31	/** The four token columns on Build, from a Usage. */
32	function usageColumns(u: Usage) {
33	  return {
34	    inputTokens: u.inputTokens,
35	    outputTokens: u.outputTokens,
36	    cacheReadTokens: u.cacheReadTokens,
37	    cacheWriteTokens: u.cacheWriteTokens,
38	  };
39	}
40	
41	export async function POST(req: Request) {
42	  const user = await getCurrentUser();
43	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
44	
45	  const body = (await req.json().catch(() => null)) as {
46	    projectId?: string;
47	    prompt?: string;
48	    image?: string;
49	  } | null;
50	  const prompt = body?.prompt?.trim();
51	  if (!body?.projectId || !prompt) {
52	    return Response.json({ error: "Missing project or prompt." }, { status: 400 });
53	  }
54	
55	  // Only a data: URL (what the client-side downscale in PromptHero produces)
56	  // is accepted — anything else is silently dropped rather than passed on.
57	  const imageMatch = body.image?.match(/^data:(image\/(?:png|jpeg|webp));base64,(.+)$/);
58	  const image = imageMatch ? { mediaType: imageMatch[1], data: imageMatch[2] } : undefined;
59	
60	  const project = await db.project.findFirst({
61	    where: { id: body.projectId, userId: user.id },
62	    include: { messages: { orderBy: { createdAt: "asc" } } },
63	  });
64	  if (!project) return Response.json({ error: "Project not found." }, { status: 404 });
65	
66	  // ── Kill switch ──────────────────────────────────────────────────────────
67	  // Placed after the project lookup (so an unknown project still 404s, and the
68	  // switch never leaks the existence of someone else's project) and before
69	  // EVERY spend path below it: the balance read, the spend cap, the Build row,
70	  // the user Message row and the model call in runAgent. Refusing here writes
71	  // nothing at all and charges nothing at all.
72	  //
73	  // Its own status and its own words, deliberately. The two checks immediately
74	  // below both answer 402 and both talk about credits; reusing either would
75	  // tell the user they are out of money during an incident that has nothing to
76	  // do with their balance, and they would go and top up. 503 is the honest
77	  // code: the capability is temporarily withdrawn by us.
78	  //
79	  // Bucketed on user.id — stable per user, so a partial rollout (if this were
80	  // ever operated as one) cannot flip the same person between requests.
81	  if (!(await isEnabled(FLAGS.generation, user.id))) {
82	    return Response.json(
83	      {
84	        error:
85	          "Building is paused right now while we sort out a problem on our side. Nothing has been charged and your project is untouched — please try again in a few minutes.",
86	      },
87	      { status: 503 },
88	    );
89	  }
90	
91	  const balance = await getBalance(user.id);
92	  if (balance <= 0) {
93	    track(EVENTS.creditsExhausted, { userId: user.id, props: { projectId: project.id } });
94	    return Response.json(
95	      { error: "You're out of credits. Top up to keep building." },
96	      { status: 402 },
97	    );
98	  }
99	
100	  // The user's own ceiling, checked before anything is spent. Distinct from
101	  // running out of credits: they still HAVE the balance, they asked us not to
102	  // burn past this without them saying so. The message says exactly that, so
103	  // it never reads as a surprise limit we imposed.
104	  const cap = await getSpendCapStatus(user.id);
105	  if (cap.reached) {
106	    track(EVENTS.spendCapReached, {
107	      userId: user.id,
108	      props: { cap: cap.cap, spent: cap.spent, projectId: project.id },
109	    });
110	    return Response.json(
111	      {
112	        error: `You've hit your own spending cap of ${cap.cap} credits per 30 days (${cap.spent} used). Raise or remove it in Settings to keep building.`,
113	        spendCapReached: true,
114	      },
115	      { status: 402 },
116	    );
117	  }
118	
119	  const rateLimit = await checkGenerateRateLimit(user.id);
120	  if (!rateLimit.allowed) {
121	    return Response.json(
122	      { error: "You're generating too fast — take a short break and try again shortly." },
123	      { status: 429, headers: { "Retry-After": String(rateLimit.retryAfterSeconds) } },
124	    );
125	  }
126	
127	  // The foundation means source files are never empty — "first build" is
128	  // instead "first real customization request" for this project.
129	  const kind = project.messages.length === 0 ? "create" : "edit";
130	
131	  const build = await db.build.create({
132	    data: { projectId: project.id, status: "RUNNING", model: "", prompt },
133	  });
134	
135	  track(EVENTS.buildStarted, {
136	    userId: user.id,
137	    props: {
138	      buildId: build.id,
139	      projectId: project.id,
140	      kind,
141	      hasImage: Boolean(image),
142	      // Only meaningful on an edit — a first build has no prior output to be
143	      // reacting to. Left off `create` so followUpIntents() isn't diluted by
144	      // rows that were never follow-ups.
145	      ...(kind === "edit" ? { intent: classifyFollowUp(prompt) } : {}),
146	    },
147	  });
148	
149	  await db.message.create({
150	    data: { projectId: project.id, role: "user", content: prompt },
151	  });
152	
153	  // Aborted when the client disconnects (tab closed, network drop) — cancels
154	  // the in-flight Anthropic request instead of burning tokens for nobody.
155	  const abortController = new AbortController();
156	
157	  const encoder = new TextEncoder();
158	  const stream = new ReadableStream({
159	    async start(controller) {
160	      // A client disconnect races with our own sends: enqueue on a closed
161	      // controller throws "Controller is already closed", which used to be
162	      // caught as a generic failure and wrongly mark an otherwise-fine build
163	      // FAILED. There's nothing to do about a gone client — swallow it.
164	      const send = (event: unknown) => {
165	        try {
166	          controller.enqueue(encoder.encode(sse(event)));
167	        } catch {
168	          // client is gone
169	        }
170	      };
171	
172	      let filesWritten = 0;
173	      let succeeded = false;
174	      // 0 means it compiled first try. This is the raw material for the
175	      // green-build-first-try metric (see greenBuildRate in lib/events.ts),
176	      // which the roadmap treats as a gate but nothing measured before.
177	      // Declared out here so the catch below can record it too.
178	      let repairAttempts = 0;
179	      // Usage kept PER ATTEMPT, not as one accumulator. A single running total
180	      // cannot tell the customer's request apart from the model repairing its
181	      // own broken output, and rule 4 of the anti-bill-shock contract charges
182	      // only the former (see settleBuild in lib/credits.ts). The run's true
183	      // total is still recorded — it is just sumUsage(attemptUsage) now.
184	      const attemptUsage: Usage[] = [];
185	      let model = "";
186	      let lastReply = "";
187	      let lastProgress = "";
188	
189	      const readSourceFiles = async (): Promise<FileMap> => {
190	        const rows = await db.projectFile.findMany({
191	          where: { projectId: project.id, published: false, kind: "source" },
192	        });
193	        return Object.fromEntries(rows.map((f) => [f.path, f.content]));
194	      };
195	
196	      try {
197	        // The project's brand kit, prepended to the FIRST request only.
198	        //
199	        // The repair loop below reassigns `request` on purpose: a repair pass
200	        // is about a compile error, not about the brand, and re-sending the
201	        // kit there would pay for it twice for no benefit.
202	        //
203	        // Without this the kit still reaches the generated site — the palette
204	        // is spliced into src/index.css as a Tailwind @theme block and the logo
205	        // is a real component — but the builder is never TOLD about it, so it
206	        // has no reason to use either.
207	        const brandRow = await db.projectFile.findFirst({
208	          where: { projectId: project.id, path: "brand.json", kind: "brand", published: false },
209	          select: { content: true },
210	        });
211	        const brand = brandRow ? parseStoredBrandKit(brandRow.content) : null;
212	
213	        let request = brand ? `${brandPromptFragment(brand)}\n\n${prompt}` : prompt;
214	        let buildOutput: FileMap | null = null;
215	        let lastBuildError = "";
216	
217	        // Resolved ONCE, outside the retry loop, so a repair pass can never run
218	        // on a different engine than the attempt it is repairing.
219	        //
220	        // Only ever an upgrade: runAgent treats KODELY_ENGINE=sdk as an
221	        // absolute pin and ignores this, so the flag cannot revoke an
222	        // operator's deliberate choice to stay off the metered key. Bucketed on
223	        // user.id, not per build — splitting one person's builds across both
224	        // engines would contaminate any comparison between them.
225	        const engine = (await isEnabled(FLAGS.sdkEngine, user.id)) ? "sdk" : "api";
226	
227	        for (let attempt = 1; attempt <= MAX_BUILD_ATTEMPTS; attempt++) {
228	          if (abortController.signal.aborted) break;
229	
230	          const attemptTotals: Usage = {
231	            inputTokens: 0,
232	            outputTokens: 0,
233	            cacheReadTokens: 0,
234	            cacheWriteTokens: 0,
235	          };
236	          attemptUsage.push(attemptTotals);
237	
238	          const generator = runAgent({
239	            engine,
240	            history: project.messages.map((m) => ({
241	              role: m.role === "assistant" ? ("assistant" as const) : ("user" as const),
242	              content: m.content,
243	            })),
244	            request,
245	            files: await readSourceFiles(),
246	            kind,
247	            // Only attached on the very first turn of a project — a repair
248	            // retry re-sends the same `request` text but should not attach
249	            // the image again mid-loop.
250	            image: attempt === 1 ? image : undefined,
251	            signal: abortController.signal,
252	            onWrite: async (path, content) => {
253	              if (!normalizePath(path)) return false;
254	              await db.projectFile.upsert({
255	                where: {
256	                  projectId_path_published_kind: {
257	                    projectId: project.id,
258	                    path,
259	                    published: false,
260	                    kind: "source",
261	                  },
262	                },
263	                create: { projectId: project.id, path, content, published: false, kind: "source" },
264	                update: { content },
265	              });
266	              filesWritten++;
267	              return true;
268	            },
269	            onDelete: async (path) => {
270	              const { count } = await db.projectFile.deleteMany({
271	                where: { projectId: project.id, path, published: false, kind: "source" },
272	              });
273	              return count > 0;
274	            },
275	          });
276	
277	          for await (const event of generator) {
278	            if (event.type === "text") {
279	              lastReply += event.text;
280	              send(event);
281	            } else if (event.type === "file") {
282	              send(event);
283	            } else if (event.type === "status") {
284	              send(event);
285	            } else if (event.type === "progress") {
286	              // Collapse consecutive identical lines. A run of twelve Reads
287	              // narrates as one "Looking through the project" rather than
288	              // twelve, which would read as a stutter rather than progress.
289	              if (event.text !== lastProgress) {
290	                lastProgress = event.text;
291	                send(event);
292	              }
293	            } else if (event.type === "usage") {
294	              model = event.model;
295	              attemptTotals.inputTokens += event.inputTokens;
296	              attemptTotals.outputTokens += event.outputTokens;
297	              attemptTotals.cacheReadTokens += event.cacheReadTokens;
298	              attemptTotals.cacheWriteTokens += event.cacheWriteTokens;
299	            }
300	          }
301	
302	          if (abortController.signal.aborted) break;
303	
304	          try {
305	            send({ type: "progress", text: "Compiling the site" });
306	            buildOutput = await buildSite(await readSourceFiles());
307	            break; // compiled cleanly — done
308	          } catch (err) {
309	            lastBuildError = err instanceof BuildError ? err.message : String(err);
310	            if (attempt >= MAX_BUILD_ATTEMPTS) throw new Error(lastBuildError);
311	            repairAttempts++;
312	            // Clear the dedupe key: the repair pass legitimately repeats the
313	            // same lines, and suppressing them would look like a stall.
314	            lastProgress = "";
315	            send({ type: "status", text: "Build didn't compile — fixing it…" });
316	            request = `The last change failed to build. Fix it and keep the rest of the change. Build error:\n${lastBuildError}`;
317	          }
318	        }
319	
320	        if (abortController.signal.aborted || !buildOutput) {
321	          // Loop ended without a successful build and without throwing —
322	          // only reachable via the abort path (see the `break` above).
323	        } else {
324	          succeeded = true;
325	
326	          // Replace the compiled tree with the new build output.
327	          await db.$transaction([
328	            db.projectFile.deleteMany({ where: { projectId: project.id, published: false, kind: "build" } }),
329	            ...(Object.keys(buildOutput).length > 0
330	              ? [
331	                  db.projectFile.createMany({
332	                    data: Object.entries(buildOutput).map(([path, content]) => ({
333	                      projectId: project.id,
334	                      path,
335	                      content,
336	                      published: false,
337	                      kind: "build",
338	                    })),
339	                  }),
340	                ]
341	              : []),
342	          ]);
343	
344	          // costMicros is the WHOLE run — every attempt, recorded as spent.
345	          // credits is only the customer's own attempt; a repair pass is our
346	          // mistake and our cost. See settleBuild in lib/credits.ts.
347	          const totals = sumUsage(attemptUsage);
348	          const settlement = settleBuild(model, attemptUsage);
349	          const { costMicros: micros, credits } = settlement;
350	          // A zero charge writes no ledger row. The ledger is a financial
351	          // record; an entry that moves nothing is noise in a statement a
352	          // customer may one day be reading to understand their bill.
353	          const remaining =
354	            credits > 0
355	              ? await chargeForBuild(user.id, build.id, credits)
356	              : await getBalance(user.id);
357	
358	          const sourceFiles = await readSourceFiles();
359	          const filesSnapshot = { source: sourceFiles, build: buildOutput };
360	
361	          await db.build.update({
362	            where: { id: build.id },
363	            data: {
364	              status: "SUCCEEDED",
365	              model,
366	              endedAt: new Date(),
367	              ...usageColumns(totals),
368	              filesWritten,
369	              repairAttempts,
370	              costMicros: micros,
371	              creditsCharged: credits,
372	              filesSnapshot,
373	            },
374	          });
375	
376	          track(EVENTS.buildSucceeded, {
377	            userId: user.id,
378	            props: {
379	              buildId: build.id,
380	              projectId: project.id,
381	              kind,
382	              model,
383	              repairAttempts,
384	              filesWritten,
385	              credits,
386	              remaining,
387	              // What rule 4 cost us on this build. Separate from `credits` so
388	              // the absorbed total is measurable without re-deriving it from
389	              // costMicros in every query.
390	              waivedCredits: settlement.waivedCredits,
391	              waivedMicros: settlement.waivedMicros,
392	            },
393	          });
394	
395	          if (lastReply.trim()) {
396	            await db.message.create({
397	              data: { projectId: project.id, role: "assistant", content: lastReply.trim() },
398	            });
399	          }
400	          await db.project.update({ where: { id: project.id }, data: { updatedAt: new Date() } });
401	
402	          // buildId travels to the client so it can attach a rating to this
403	          // specific build (see app/api/feedback/route.ts).
404	          //
405	          // repairWaived/waivedCredits make rule 4 visible instead of a silent
406	          // internal policy. The user watched "Build didn't compile — fixing
407	          // it…" go past; without this the next thing they see is a charge and
408	          // no statement that the fixing part was free. Editor.tsx ignores
409	          // fields it does not know, so it is safe to send today and to render
410	          // whenever that component is updated.
411	          send({
412	            type: "done",
413	            credits,
414	            remaining,
415	            filesWritten,
416	            buildId: build.id,
417	            repairAttempts,
418	            repairWaived: settlement.repairWaived,
419	            waivedCredits: settlement.waivedCredits,
420	          });
421	        }
422	
423	        if (!succeeded) {
424	          const spent = sumUsage(attemptUsage);
425	          await db.build.update({
426	            where: { id: build.id },
427	            data: {
428	              status: "FAILED",
429	              endedAt: new Date(),
430	              error: abortController.signal.aborted ? "Client disconnected." : "Generation ended without producing output.",
431	              filesWritten,
432	              repairAttempts,
433	              creditsCharged: 0,
434	              // Charged zero, but the tokens were still spent. Rule 3 says a
435	              // failed build is "recorded with its true cost and charged
436	              // ZERO"; the recording half was missing, so every failure showed
437	              // $0.0000 in /admin and the give-away figure on
438	              // /admin/analytics was understated by exactly the cost of every
439	              // build that never worked. Under rule 4 that matters more, not
440	              // less: a run that burned two attempts and still failed is the
441	              // most expensive thing we absorb.
442	              ...usageColumns(spent),
443	              costMicros: costMicros(model, spent),
444	              // Record the model on failure too, when we got far enough to
445	              // learn it. It used to be written only on success, so every
446	              // failed build had a blank Model column — which made it
447	              // impossible to attribute a spike in failures to a model change,
448	              // exactly when you most need to.
449	              ...(model ? { model } : {}),
450	            },
451	          });
452	
453	          track(EVENTS.buildFailed, {
454	            userId: user.id,
455	            props: {
456	              buildId: build.id,
457	              projectId: project.id,
458	              kind,
459	              repairAttempts,
460	              reason: abortController.signal.aborted ? "aborted" : "no_output",
461	            },
462	          });
463	        }
464	      } catch (error) {
465	        // A build that fails is never charged — that is the product promise,
466	        // so the ledger is deliberately untouched on this path.
467	        const message =
468	          error instanceof Error ? error.message : "The build failed unexpectedly.";
469	        console.error("[kodely] build failed", build.id, error);
470	
471	        // Same as the other failure path: charged zero, recorded honestly.
472	        const spent = sumUsage(attemptUsage);
473	
474	        await db.build.update({
475	          where: { id: build.id },
476	          data: {
477	            status: "FAILED",
478	            endedAt: new Date(),
479	            error: message.slice(0, 1000),
480	            filesWritten,
481	            repairAttempts,
482	            creditsCharged: 0,
483	            ...usageColumns(spent),
484	            costMicros: costMicros(model, spent),
485	            // See the note on the other failure path — a blank model makes a
486	            // failure impossible to attribute.
487	            ...(model ? { model } : {}),
488	          },
489	        });
490	
491	        track(EVENTS.buildFailed, {
492	          userId: user.id,
493	          props: {
494	            buildId: build.id,
495	            projectId: project.id,
496	            kind,
497	            repairAttempts,
498	            reason: "error",
499	          },
500	        });
501	
502	        send({ type: "error", message });
503	      } finally {
504	        try {
505	          controller.close();
506	        } catch {
507	          // already closed by the client disconnect path
508	        }
509	      }
510	    },
511	    cancel() {
512	      // The client disconnected — stop the in-flight Anthropic request
513	      // rather than let it run to completion for a response nobody reads.
514	      abortController.abort();
515	    },
516	  });
517	
518	  return new Response(stream, {
519	    headers: {
520	      "Content-Type": "text/event-stream; charset=utf-8",
521	      "Cache-Control": "no-cache, no-transform",
522	      Connection: "keep-alive",
523	    },
524	  });
525	}
