3	export type StepState = "done" | "active" | "pending" | "failed";
4	export type ProgressStep = { id: string; label: string; state: StepState };
5	
6	/* THE single AI-progress component. The initial build overlay, the chat panel
7	   during an edit, and the preview's busy state all render this same list, so
8	   "Kodely is working" looks like one object the customer follows across three
9	   places rather than three unrelated spinners.
10	
11	   Why a step LIST and not a percentage: the build genuinely does not know how
12	   far along it is — it is an agent loop of unknown length — and a progress bar
13	   that jumps or stalls at 80% is a worse lie than an honest sequence of named
14	   steps. What it does know is which phase it is in, so that is what is shown.
15	
16	   Callers must drive `state` from real signals. A timer that walks the list
17	   forward on its own would be a fake, and would still be sitting on
18	   "Finalizing" long after a build had failed. */
19	export function AIProgress({
20	  steps,
21	  className = "",
22	}: {
23	  steps: ProgressStep[];
24	  className?: string;
25	}) {
26	  return (
27	    <ol
28	      className={`flex flex-col gap-2 ${className}`}
29	      // Each step's arrival is announced once as it changes, which is the
30	      // whole point of the component for a screen-reader user — they get the
31	      // same "it is working, here is where it is" that sighted users get.
32	      aria-live="polite"
33	      aria-atomic="false"
34	    >
35	      {steps.map((s, i) => (
36	        <li
37	          key={s.id}
38	          className="k-step-in flex items-center gap-2.5 text-[0.8125rem]"
39	          style={{ animationDelay: `${i * 55}ms` }}
40	        >
41	          <StepIcon state={s.state} />
42	          <span
43	            className={
44	              s.state === "pending"
45	                ? "text-ink-3"
46	                : s.state === "failed"
47	                  ? "text-danger"
48	                  : s.state === "active"
49	                    ? "font-medium text-ink"
50	                    : "text-ink-2"
51	            }
52	          >
53	            {s.label}
54	          </span>
55	        </li>
56	      ))}
57	    </ol>
58	  );
59	}
60	
61	function StepIcon({ state }: { state: StepState }): ReactNode {
62	  if (state === "done") {
63	    return (
64	      <span className="grid size-4 shrink-0 place-items-center rounded-full bg-ok-tint">
65	        <svg viewBox="0 0 24 24" className="size-2.5 text-ok" fill="none" stroke="currentColor" strokeWidth="3.5" strokeLinecap="round" strokeLinejoin="round">
66	          <path d="m4 12.5 5 5L20 7" />
67	        </svg>
68	      </span>
69	    );
70	  }
71	  if (state === "failed") {
72	    return (
73	      <span className="grid size-4 shrink-0 place-items-center rounded-full bg-danger-tint">
74	        <svg viewBox="0 0 24 24" className="size-2.5 text-danger" fill="none" stroke="currentColor" strokeWidth="3.5" strokeLinecap="round">
75	          <path d="m6 6 12 12M18 6 6 18" />
76	        </svg>
77	      </span>
78	    );
79	  }
80	  if (state === "active") {
81	    return (
82	      <span className="grid size-4 shrink-0 place-items-center">
83	        <span className="k-step-active size-2.5 rounded-full bg-brand" />
84	      </span>
85	    );
86	  }
87	  return (
88	    <span className="grid size-4 shrink-0 place-items-center">
89	      <span className="size-2.5 rounded-full border border-line-strong" />
90	    </span>
91	  );
92	}
93	
94	/** Advances a step list to `activeIndex`. Kept here so the two callers cannot
95	    disagree about what "everything before the active one is done" means. */
96	export function stepsAt(labels: readonly { id: string; label: string }[], activeIndex: number, failed = false): ProgressStep[] {
97	  return labels.map((l, i) => ({
98	    ...l,
99	    state:
100	      i < activeIndex ? "done" : i === activeIndex ? (failed ? "failed" : "active") : "pending",
101	  }));
102	}
