/**
 * The step machine behind the build-start experience.
 *
 * ─────────────────────────────────────────────────────────────────────────────
 * WHY THIS FILE EXISTS AS A PURE REDUCER
 * ─────────────────────────────────────────────────────────────────────────────
 * `AIProgress` is only honest if every step change is caused by something that
 * actually happened. Keeping the mapping here — with no timers, no `setTimeout`
 * and no access to the clock — makes that structurally true rather than a
 * promise in a comment: this module CANNOT advance a step on its own, because
 * the only way to move it is to hand it a signal.
 *
 * ─────────────────────────────────────────────────────────────────────────────
 * THE REAL SSE VOCABULARY OF /api/generate  (audited 2026-08-22)
 * ─────────────────────────────────────────────────────────────────────────────
 * `app/api/generate/route.ts` writes `data: <json>\n\n` frames. Exactly six
 * event shapes ever reach the client:
 *
 *   { type: "text",     text }                 assistant prose deltas
 *   { type: "progress", text }                 one narrated tool call
 *   { type: "status",   text }                 a phase the server names itself
 *   { type: "file",     path, action }         a source file was written/deleted
 *   { type: "done",     credits, remaining, filesWritten, buildId,
 *                       repairAttempts, repairWaived, waivedCredits }
 *   { type: "error",    message }
 *
 * A seventh, `{ type: "usage", … }`, is produced by the agent but consumed
 * server-side for billing and is NEVER forwarded — so the client cannot see
 * token spend while a build runs.
 *
 * The two text channels are NOT free-form. Their producers are enumerable:
 *
 *   `progress` — `narrateTool()` in lib/build-narration.ts, one line per real
 *     tool call, with consecutive duplicates collapsed by the route:
 *       "Writing <thing>" / "Writing a file"      (Write, write_file)
 *       "Updating <thing>" / "Making an edit"     (Edit)
 *       "Removing <thing>" / "Removing a file"    (delete_file)
 *       "Looking through the project"             (Read, Glob, Grep)
 *       "Running a command"                       (Bash)
 *     plus two the route/agent emit directly:
 *       "Picking out icons and artwork"           (lib/agent.ts asset tool)
 *       "Compiling the site"                      (route, before buildSite())
 *
 *   `status` — only two producers:
 *       "Building your site…" / "Applying your changes…"  (SDK engine, once)
 *       "Build didn't compile — fixing it…"               (route, per repair)
 *
 * ─────────────────────────────────────────────────────────────────────────────
 * WHAT THAT VOCABULARY CAN AND CANNOT SUPPORT
 * ─────────────────────────────────────────────────────────────────────────────
 * The brief asked for six steps: understanding, planning, designing,
 * generating, content, finalizing. Four of those six are NOT observable. The
 * stream carries no "planning" marker, no "designing" marker and no way to
 * separate layout work from copy work — a write to `src/components/Hero.tsx`
 * is one `file` event whether the model was laying out a grid or writing the
 * headline. Rendering all six would mean inventing four of them, and a step
 * that lights up because 4 seconds elapsed is exactly the fake this redesign
 * exists to remove.
 *
 * So there are FIVE steps, and each one is entered or completed by a specific
 * observable fact:
 *
 *   0 project    done when POST /api/projects returns a project id
 *   1 sending    done when POST /api/generate answers 200 with a body — which
 *                means credits, spend cap, rate limit and the kill switch all
 *                passed and a Build row exists
 *   2 thinking   done at the first evidence of a WRITE (a `file` event, or a
 *                `progress` line from the Write/Edit/delete_file branch)
 *   3 writing    done when the route sends `progress: "Compiling the site"`
 *   4 compiling  done on `done`
 *
 * And the list can move BACKWARD: `status: "Build didn't compile — fixing it…"`
 * returns the active step to `writing`, because that is what the server just
 * did. An `error` freezes the list and marks the step it died on as failed.
 */

/** The literal the route sends immediately before `buildSite()`. */
const COMPILING_LINE = "Compiling the site";

/** The literal the route sends before a repair pass. Matched on the stable
    leading clause rather than the whole string, so the trailing wording can
    change without silently breaking the mapping. */
const REPAIR_PREFIX = /^Build didn't compile/;

/** Every `narrateTool` branch that means a file was touched. `Making an edit`
    is the Edit branch when the tool call carried no readable path. */
const WRITE_LINE = /^(Writing|Updating|Removing|Making an edit)\b/;

export const BUILD_STEPS = [
  { id: "project", label: "Creating your project" },
  { id: "sending", label: "Sending your brief to Kodely" },
  { id: "thinking", label: "Reading the brief and the starter files" },
  { id: "writing", label: "Writing your site's files" },
  { id: "compiling", label: "Compiling the site" },
] as const;

const STEP = {
  project: 0,
  sending: 1,
  thinking: 2,
  writing: 3,
  compiling: 4,
} as const;

/** One frame off the wire, after narrowing. */
export type StreamEvent =
  | { type: "text"; text: string }
  | { type: "progress"; text: string }
  | { type: "status"; text: string }
  | { type: "file"; path: string; action: string }
  | {
      type: "done";
      credits: number;
      remaining: number;
      filesWritten: number;
      buildId: string | null;
      repairAttempts: number;
      repairWaived: boolean;
      waivedCredits: number;
    }
  | { type: "error"; message: string };

function str(v: unknown, fallback = ""): string {
  return typeof v === "string" ? v : fallback;
}
function num(v: unknown, fallback = 0): number {
  return typeof v === "number" && Number.isFinite(v) ? v : fallback;
}

/**
 * Narrow one parsed SSE payload. Returns null for anything unrecognised —
 * a frame we cannot read must not move the step list, and must not throw and
 * kill a build that is otherwise going fine.
 */
export function parseStreamEvent(raw: unknown): StreamEvent | null {
  if (typeof raw !== "object" || raw === null) return null;
  const e = raw as Record<string, unknown>;
  switch (e.type) {
    case "text":
      return { type: "text", text: str(e.text) };
    case "progress":
      return { type: "progress", text: str(e.text) };
    case "status":
      return { type: "status", text: str(e.text) };
    case "file":
      return { type: "file", path: str(e.path), action: str(e.action) };
    case "done":
      return {
        type: "done",
        credits: num(e.credits),
        remaining: num(e.remaining),
        filesWritten: num(e.filesWritten),
        buildId: typeof e.buildId === "string" ? e.buildId : null,
        repairAttempts: num(e.repairAttempts),
        repairWaived: e.repairWaived === true,
        waivedCredits: num(e.waivedCredits),
      };
    case "error":
      return { type: "error", message: str(e.message, "The build failed.") };
    default:
      return null;
  }
}

export type BuildOutcome = "running" | "succeeded" | "failed";

export type BuildProgress = {
  /** Index into BUILD_STEPS of the step currently in flight. */
  index: number;
  outcome: BuildOutcome;
  /** The most recent `progress`/`status` line, verbatim. The raw signal. */
  line: string | null;
  /** `file` events seen. On the SDK engine these can arrive in one batch. */
  filesTouched: number;
  /** Repair passes the SERVER announced. Never inferred. */
  repairs: number;
  buildId: string | null;
  credits: number | null;
  remaining: number | null;
  error: string | null;
  /** True once any byte of the stream has been read. Distinguishes "refused
      before it started" (safe to retry on the same project) from "died
      mid-build" (a user message row already exists, so a retry would be an
      edit rather than a first build). */
  streamStarted: boolean;
};

export const INITIAL_BUILD: BuildProgress = {
  index: STEP.project,
  outcome: "running",
  line: null,
  filesTouched: 0,
  repairs: 0,
  buildId: null,
  credits: null,
  remaining: null,
  error: null,
  streamStarted: false,
};

export type BuildSignal =
  /** POST /api/projects resolved with an id. */
  | { kind: "project-created" }
  /** POST /api/generate answered 200 and handed back a readable body. */
  | { kind: "accepted" }
  /** One frame off the stream. */
  | { kind: "sse"; event: StreamEvent }
  /** The request was refused, or the fetch itself threw. */
  | { kind: "failed"; message: string }
  /** The stream closed without a `done` or an `error`. */
  | { kind: "lost" }
  /** The customer pressed Stop. */
  | { kind: "stopped" };

const LOST_MESSAGE =
  "The connection to the build dropped before it finished. Nothing was charged — open the project to see what was written and try again there.";

const STOPPED_MESSAGE =
  "You stopped the build. Nothing was charged. Any files written before you stopped are already in the project.";

/** Pure. The ONLY way BuildProgress changes. */
export function reduceBuild(state: BuildProgress, signal: BuildSignal): BuildProgress {
  if (state.outcome !== "running") return state;

  switch (signal.kind) {
    case "project-created":
      return { ...state, index: Math.max(state.index, STEP.sending) };

    case "accepted":
      return { ...state, index: Math.max(state.index, STEP.thinking) };

    case "failed":
      return { ...state, outcome: "failed", error: signal.message };

    case "lost":
      return { ...state, outcome: "failed", error: LOST_MESSAGE };

    case "stopped":
      return { ...state, outcome: "failed", error: STOPPED_MESSAGE };

    case "sse":
      return applyEvent({ ...state, streamStarted: true }, signal.event);
  }
}

function applyEvent(state: BuildProgress, event: StreamEvent): BuildProgress {
  switch (event.type) {
    // Prose from the model. Real evidence the request is being worked on, but
    // it names no phase, so it moves nothing beyond "the stream is alive".
    case "text":
      return state;

    case "progress":
    case "status": {
      const text = event.text;
      const next = { ...state, line: text || state.line };

      // The server just told us the previous attempt did not compile. Going
      // back to `writing` is not a glitch — the build genuinely went back.
      if (REPAIR_PREFIX.test(text)) {
        return { ...next, index: STEP.writing, repairs: next.repairs + 1 };
      }
      if (text === COMPILING_LINE) {
        return { ...next, index: STEP.compiling };
      }
      if (WRITE_LINE.test(text)) {
        return { ...next, index: Math.max(next.index, STEP.writing) };
      }
      // "Looking through the project", "Running a command", "Picking out icons
      // and artwork", "Building your site…" — all real, none of them a phase
      // change. They show up in the live line and nowhere else.
      return { ...next, index: Math.max(next.index, STEP.thinking) };
    }

    case "file":
      return {
        ...state,
        filesTouched: state.filesTouched + 1,
        index: Math.max(state.index, STEP.writing),
      };

    case "done":
      return {
        ...state,
        outcome: "succeeded",
        index: BUILD_STEPS.length,
        line: null,
        buildId: event.buildId,
        credits: event.credits,
        remaining: event.remaining,
        // The server's own count is authoritative over the events we happened
        // to see — a dropped frame must not understate what was written.
        filesTouched: Math.max(state.filesTouched, event.filesWritten),
        repairs: Math.max(state.repairs, event.repairAttempts),
      };

    case "error":
      return { ...state, outcome: "failed", error: event.message };
  }
}

/**
 * Reference-image handling for the portal composer.
 *
 * Deliberately a COPY of the downscale in components/marketing/PromptHero.tsx
 * (lines 44-57) rather than an import: that file belongs to the marketing
 * system and to another owner. The two must agree on one thing only — the
 * output has to be a `data:image/(png|jpeg|webp);base64,…` URL, because that
 * regex in app/api/generate/route.ts (line 57) is the sole gate. Anything else
 * is silently dropped server-side and the customer never learns their image
 * was ignored, so this module refuses it up front instead.
 */

/** Exactly what app/api/generate/route.ts will accept. */
export const ACCEPTED_IMAGE_TYPES = ["image/png", "image/jpeg", "image/webp"] as const;

/** What the file picker offers. Narrower than `image/*` on purpose — a HEIC
    from a phone would be offered by `image/*` and then fail to decode. */
export const IMAGE_ACCEPT = ".png,.jpg,.jpeg,.webp,image/png,image/jpeg,image/webp";

export type ImageResult =
  | { ok: true; dataUrl: string; name: string; bytes: number }
  | { ok: false; error: string };

/**
 * Downscale and re-encode to JPEG. Re-encoding is what makes the result
 * predictable: whatever came in, what goes out is `data:image/jpeg;base64,…`,
 * which the generate route accepts. It also keeps a 12MP phone photo from
 * costing a fortune in image tokens for detail the model cannot use.
 */
export async function prepareReferenceImage(
  file: File,
  maxDim = 1400,
  quality = 0.82,
): Promise<ImageResult> {
  if (!(ACCEPTED_IMAGE_TYPES as readonly string[]).includes(file.type)) {
    return {
      ok: false,
      error: "That file type can't be used as a reference. Pick a PNG, JPEG or WebP image.",
    };
  }

  try {
    const bitmap = await createImageBitmap(file);
    const scale = Math.min(1, maxDim / Math.max(bitmap.width, bitmap.height));
    const w = Math.max(1, Math.round(bitmap.width * scale));
    const h = Math.max(1, Math.round(bitmap.height * scale));
    const canvas = document.createElement("canvas");
    canvas.width = w;
    canvas.height = h;
    const ctx = canvas.getContext("2d");
    if (!ctx) return { ok: false, error: "This browser couldn't read that image." };
    ctx.drawImage(bitmap, 0, 0, w, h);
    bitmap.close();

    const dataUrl = canvas.toDataURL("image/jpeg", quality);
    if (!dataUrl.startsWith("data:image/jpeg;base64,")) {
      return { ok: false, error: "This browser couldn't re-encode that image." };
    }
    // Base64 of the payload, minus the `data:image/jpeg;base64,` prefix.
    const bytes = Math.round((dataUrl.length - 23) * 0.75);
    return { ok: true, dataUrl, name: file.name, bytes };
  } catch {
    return { ok: false, error: "That image couldn't be read. Try a different one." };
  }
}

"use client";

import Link from "next/link";
import { useRef, useState } from "react";
import { ArrowUp, ImagePlus, LayoutTemplate, Wand2, X } from "lucide-react";
import { Badge } from "@/components/ui/Badge";
import { Button, ButtonLink } from "@/components/ui/Button";
import { Textarea } from "@/components/ui/Field";
import { IMAGE_ACCEPT, prepareReferenceImage } from "./image";

/* One-tap starters. Short on purpose — these are a way in, not a brief; the
   fully-written briefs live at /dashboard/templates. Each one describes a
   site this product can genuinely produce: one page, no backend. */
const EXAMPLES = [
  "A one-page site for my barbershop with services, prices and hours",
  "A portfolio for a freelance product designer",
  "A landing page for a project-tracking tool for small agencies",
  "A neighbourhood coffee shop page with a drinks list and opening hours",
  "A launch page for a hardcover book I'm selling",
  "A wedding info page with the schedule, travel and dress code",
];

export type CreditContext = {
  balance: number;
  estimate: { low: number; high: number };
  cap: { cap: number | null; spent: number; remaining: number | null; reached: boolean };
};

export function Composer({
  value,
  onChange,
  onSubmit,
  fromTemplate,
  credits,
  billingHref,
}: {
  value: string;
  onChange: (v: string) => void;
  onSubmit: (prompt: string, image: string | null) => void;
  fromTemplate: string | null;
  credits: CreditContext;
  billingHref: string;
}) {
  const [image, setImage] = useState<{ dataUrl: string; name: string; bytes: number } | null>(null);
  const [imageError, setImageError] = useState<string | null>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const boxRef = useRef<HTMLTextAreaElement>(null);

  const { balance, estimate, cap } = credits;
  const outOfCredits = balance <= 0;
  const capReached = cap.reached;
  const tight = !outOfCredits && balance < estimate.high;
  const capTight =
    !capReached && cap.remaining !== null && cap.remaining < estimate.high;

  const blocked = outOfCredits || capReached;
  const ready = value.trim().length > 0 && !blocked;

  function useExample(text: string) {
    onChange(text);
    const box = boxRef.current;
    if (box) {
      box.focus();
      requestAnimationFrame(() => box.setSelectionRange(box.value.length, box.value.length));
    }
  }

  async function pickImage(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file) return;
    setImageError(null);
    const result = await prepareReferenceImage(file);
    if (result.ok) setImage({ dataUrl: result.dataUrl, name: result.name, bytes: result.bytes });
    else setImageError(result.error);
  }

  return (
    <div className="mx-auto w-full max-w-3xl">
      <header className="pt-6 text-center sm:pt-14">
        <h1 className="k-display text-ink">What do you want to build?</h1>
        <p className="mx-auto mt-3 max-w-xl text-[0.9375rem] leading-relaxed text-ink-2">
          Describe it in your own words. Kodely writes a real one-page site —
          React, Tailwind, your copy — and you keep editing it by asking for
          changes.
        </p>
      </header>

      {/* The one hero panel on this page. `k-wash` is the ambient brand glow
          the design system reserves for exactly this: one per page, and this
          is the element the whole screen is built around. */}
      <section className="relative mt-8 overflow-hidden rounded-2xl border border-hair bg-surface p-4 shadow-e2 sm:p-5">
        <div className="k-wash" aria-hidden />

        <div className="relative">
          {fromTemplate !== null && (
            <div className="mb-3 flex flex-wrap items-center gap-2">
              <Badge tone="brand">Started from “{fromTemplate}”</Badge>
              <span className="text-xs text-ink-3">
                It is just text — change anything before you build.
              </span>
            </div>
          )}

          <Textarea
            ref={boxRef}
            label="Describe the website you want to create"
            className="min-h-40 border-transparent bg-transparent text-[0.9375rem] sm:min-h-44"
            placeholder="Describe the website you want to create…"
            value={value}
            onChange={(e) => onChange(e.target.value)}
            onKeyDown={(e) => {
              // Cmd/Ctrl+Enter submits. Plain Enter must not: a brief worth
              // building is several paragraphs, and losing a paragraph break
              // to an accidental build costs real credits.
              if (e.key === "Enter" && (e.metaKey || e.ctrlKey) && ready) {
                e.preventDefault();
                onSubmit(value.trim(), image?.dataUrl ?? null);
              }
            }}
            hint="The more specific you are — sections, tone, what to leave as a placeholder — the closer the first build lands."
          />

          {image !== null && (
            <div className="mt-3 flex items-center gap-3 rounded-lg border border-hair bg-surface-2 p-2">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={image.dataUrl}
                alt={`Reference image: ${image.name}`}
                className="size-12 shrink-0 rounded-md object-cover"
              />
              <div className="min-w-0 flex-1">
                <p className="truncate text-[0.8125rem] font-medium text-ink">{image.name}</p>
                <p className="k-num text-xs text-ink-3">
                  Resized to about {Math.max(1, Math.round(image.bytes / 1024))} KB · sent with the
                  first attempt only
                </p>
              </div>
              <Button
                variant="ghost"
                size="sm"
                icon={<X size={14} />}
                onClick={() => setImage(null)}
              >
                Remove
              </Button>
            </div>
          )}

          {imageError !== null && (
            <p role="alert" className="mt-3 text-xs text-danger">
              {imageError}
            </p>
          )}

          <div className="mt-4 flex flex-wrap items-center justify-between gap-3">
            <div className="flex flex-wrap items-center gap-1">
              <input
                ref={fileRef}
                type="file"
                accept={IMAGE_ACCEPT}
                className="sr-only"
                onChange={pickImage}
              />
              <Button
                variant="ghost"
                size="sm"
                icon={<ImagePlus size={15} />}
                onClick={() => fileRef.current?.click()}
              >
                {image ? "Replace image" : "Add a reference image"}
              </Button>
              <ButtonLink
                href="/dashboard/templates"
                variant="ghost"
                size="sm"
                icon={<LayoutTemplate size={15} />}
              >
                Use a template
              </ButtonLink>
              <ButtonLink href="/wizard" variant="ghost" size="sm" icon={<Wand2 size={15} />}>
                Help me write it
              </ButtonLink>
            </div>

            <Button
              variant="primary"
              size="lg"
              disabled={!ready}
              iconRight={<ArrowUp size={16} strokeWidth={2.5} />}
              onClick={() => onSubmit(value.trim(), image?.dataUrl ?? null)}
            >
              Build my site
            </Button>
          </div>

          {/* The attachment limit, stated where the attachment control is
              rather than in small print somewhere else. A PNG/JPEG/WebP
              reference is real end to end; nothing else is, and there is no
              file upload of any kind behind this product. */}
          <p className="mt-3 text-xs leading-relaxed text-ink-3">
            Reference images only — PNG, JPEG or WebP. Kodely looks at it on the first attempt and
            uses it as visual guidance. Uploading documents, ZIPs or existing site files isn’t
            supported.
          </p>
        </div>
      </section>

      <div className="mt-5 flex flex-wrap justify-center gap-2">
        {EXAMPLES.map((example) => (
          <button
            key={example}
            type="button"
            onClick={() => useExample(example)}
            className="k-focus rounded-full border border-hair bg-surface px-3 py-1.5 text-xs text-ink-2 shadow-e1 transition-[color,border-color,background] duration-[var(--t-1)] hover:border-line-mid hover:bg-surface-2 hover:text-ink"
          >
            {example}
          </button>
        ))}
      </div>

      <div className="mt-8">
        <CreditNote
          balance={balance}
          estimate={estimate}
          outOfCredits={outOfCredits}
          tight={tight}
          cap={cap}
          capReached={capReached}
          capTight={capTight}
          billingHref={billingHref}
        />
      </div>
    </div>
  );
}

function CreditNote({
  balance,
  estimate,
  outOfCredits,
  tight,
  cap,
  capReached,
  capTight,
  billingHref,
}: {
  balance: number;
  estimate: { low: number; high: number };
  outOfCredits: boolean;
  tight: boolean;
  cap: CreditContext["cap"];
  capReached: boolean;
  capTight: boolean;
  billingHref: string;
}) {
  return (
    <div className="rounded-xl border border-hair bg-surface-2/60 p-4">
      <div className="flex flex-wrap items-baseline justify-between gap-x-6 gap-y-2">
        <p className="text-[0.8125rem] text-ink-2">
          A first build usually costs{" "}
          <span className="k-num font-semibold text-ink">
            {estimate.low}–{estimate.high}
          </span>{" "}
          credits.{" "}
          <span className="text-ink-3">
            It is a range, not a quote — the real figure depends on how much site you asked for.
          </span>
        </p>
        <p className="text-[0.8125rem] text-ink-2">
          You have <span className="k-num font-semibold text-ink">{balance}</span>
        </p>
      </div>

      <p className="mt-2 text-xs leading-relaxed text-ink-3">
        You are charged only for the attempt you asked for. If the first output doesn’t compile,
        Kodely’s repair pass is on us, and a build that fails outright costs you nothing.
      </p>

      {outOfCredits && (
        <Callout tone="danger">
          You’re out of credits, so a build would be refused before it started. Top up and this
          brief will still be here.
          <CalloutAction href={billingHref} label="Top up credits" />
        </Callout>
      )}

      {tight && (
        <Callout tone="warn">
          That’s below what a first build usually costs. Your balance is checked when a build
          starts, not while it runs — so this one can finish and take you to zero or below.
          <CalloutAction href={billingHref} label="Top up first" />
        </Callout>
      )}

      {capReached && cap.cap !== null && (
        <Callout tone="danger">
          You’ve hit the spending cap you set — <span className="k-num">{cap.spent}</span> of{" "}
          <span className="k-num">{cap.cap}</span> credits in the last 30 days. Builds are refused
          until you raise or remove it.
          <CalloutAction href="/settings" label="Change your cap" />
        </Callout>
      )}

      {capTight && cap.remaining !== null && (
        <Callout tone="warn">
          Your own spending cap leaves <span className="k-num">{cap.remaining}</span> credits in
          this 30-day window, which may not cover a full build.
          <CalloutAction href="/settings" label="Review your cap" />
        </Callout>
      )}
    </div>
  );
}

function Callout({ tone, children }: { tone: "warn" | "danger"; children: React.ReactNode }) {
  const skin =
    tone === "danger"
      ? "border-danger/25 bg-danger-tint text-danger"
      : "border-warn/25 bg-warn-tint text-warn";
  return (
    <p
      className={`mt-3 flex flex-wrap items-center gap-x-2 gap-y-1 rounded-lg border px-3 py-2 text-xs leading-relaxed ${skin}`}
    >
      {children}
    </p>
  );
}

function CalloutAction({ href, label }: { href: string; label: string }) {
  return (
    <Link
      href={href}
      className="k-focus rounded-xs font-semibold underline underline-offset-2"
    >
      {label}
    </Link>
  );
}

"use client";

import { AlertTriangle, Hammer } from "lucide-react";
import { AIProgress, stepsAt } from "@/components/ui/AIProgress";
import { Badge } from "@/components/ui/Badge";
import { Button, ButtonLink } from "@/components/ui/Button";
import { Spinner } from "@/components/ui/Spinner";
import { BUILD_STEPS, type BuildProgress } from "./build-steps";

/* The screen between "I pressed build" and "I am in the builder".
   ────────────────────────────────────────────────────────────────
   It runs the REAL build. It is not a loading screen played over a
   navigation: the SSE stream from /api/generate is open on this page, every
   step below is moved by an event off that stream, and the customer is only
   sent to /projects/<id> once the server has said `done`.

   That ordering is deliberate. Navigating mid-stream would close the response
   body, which fires `cancel()` on the route's ReadableStream, which aborts the
   model request — so "show progress here, then hand over" is the only version
   of this screen that does not silently kill the thing it is narrating. The
   copy says so rather than hoping nobody closes the tab. */
export function BuildLaunch({
  progress,
  prompt,
  projectId,
  stopping,
  onStop,
  onRetry,
  onEdit,
}: {
  progress: BuildProgress;
  prompt: string;
  projectId: string | null;
  stopping: boolean;
  onStop: () => void;
  /** Null when a retry from here would not be a first build any more. */
  onRetry: (() => void) | null;
  onEdit: () => void;
}) {
  const failed = progress.outcome === "failed";
  const succeeded = progress.outcome === "succeeded";
  const running = progress.outcome === "running";

  return (
    <div className="mx-auto w-full max-w-xl pt-6 sm:pt-14">
      <div className="k-msg-in relative overflow-hidden rounded-2xl border border-hair bg-surface p-5 shadow-e2 sm:p-7">
        <div className="k-wash" aria-hidden />

        <div className="relative">
          <div className="flex items-start justify-between gap-4">
            <div className="min-w-0">
              <h1 className="k-h1 text-ink">
                {succeeded
                  ? "Your site is built"
                  : failed
                    ? "The build stopped"
                    : "Building your site"}
              </h1>
              <p className="mt-1 text-[0.8125rem] leading-relaxed text-ink-2">
                {succeeded
                  ? "Opening the builder so you can see it and keep changing it."
                  : failed
                    ? "Nothing further will happen until you choose what to do next."
                    : "Every line below moves when the build reports it, not on a timer."}
              </p>
            </div>
            {running && (
              <Badge tone="brand" dot pulse>
                Live
              </Badge>
            )}
            {succeeded && (
              <Badge tone="ok" dot>
                Done
              </Badge>
            )}
            {failed && (
              <Badge tone="danger" dot>
                Stopped
              </Badge>
            )}
          </div>

          <blockquote className="mt-5 max-h-24 overflow-y-auto rounded-lg border border-hair bg-inset px-3 py-2.5 text-[0.8125rem] leading-relaxed whitespace-pre-wrap text-ink-2">
            {prompt}
          </blockquote>

          <div className="mt-6">
            <AIProgress steps={stepsAt(BUILD_STEPS, progress.index, failed)} />
          </div>

          {/* The raw signal, verbatim. Everything above is an interpretation of
              the stream; this is the stream. If the two ever disagree, this one
              is right. */}
          {running && (
            <div className="mt-4 flex items-center gap-2 border-t border-hair pt-4 text-xs text-ink-3">
              <Spinner size={13} className="shrink-0 text-brand" />
              <span className="truncate">
                {progress.line ?? "Waiting for the first signal from the build…"}
              </span>
            </div>
          )}

          {progress.repairs > 0 && (
            <p className="mt-3 flex items-start gap-2 rounded-lg border border-warn/25 bg-warn-tint px-3 py-2 text-xs leading-relaxed text-warn">
              <Hammer size={14} className="mt-px shrink-0" />
              <span>
                The output didn’t compile, so Kodely went back and fixed it (
                <span className="k-num">{progress.repairs}</span>{" "}
                {progress.repairs === 1 ? "pass" : "passes"}). Repair passes are not charged to
                you.
              </span>
            </p>
          )}

          {progress.filesTouched > 0 && (
            <p className="k-num mt-3 text-xs text-ink-3">
              {progress.filesTouched} file{progress.filesTouched === 1 ? "" : "s"} written so far
            </p>
          )}

          {succeeded && progress.credits !== null && (
            <p className="mt-4 rounded-lg border border-hair bg-surface-2 px-3 py-2 text-xs leading-relaxed text-ink-2">
              Charged <span className="k-num font-semibold text-ink">{progress.credits}</span>{" "}
              credits.
              {progress.remaining !== null && (
                <>
                  {" "}
                  You have <span className="k-num font-semibold text-ink">
                    {progress.remaining}
                  </span>{" "}
                  left.
                </>
              )}
            </p>
          )}

          {failed && progress.error !== null && (
            <div
              role="alert"
              className="mt-4 flex items-start gap-2 rounded-lg border border-danger/25 bg-danger-tint px-3 py-2.5 text-xs leading-relaxed text-danger"
            >
              <AlertTriangle size={14} className="mt-px shrink-0" />
              <span>{progress.error}</span>
            </div>
          )}

          <div className="mt-6 flex flex-wrap items-center gap-2 border-t border-hair pt-5">
            {running && (
              <>
                <Button variant="secondary" onClick={onStop} loading={stopping}>
                  {stopping ? "Stopping" : "Stop the build"}
                </Button>
                <p className="text-xs leading-relaxed text-ink-3">
                  Keep this tab open — leaving stops the build. A stopped build is never charged.
                </p>
              </>
            )}

            {succeeded && projectId !== null && (
              <ButtonLink href={`/projects/${projectId}`} variant="primary">
                Open the builder
              </ButtonLink>
            )}

            {failed && (
              <>
                {onRetry !== null ? (
                  <Button variant="primary" onClick={onRetry}>
                    Try again
                  </Button>
                ) : (
                  projectId !== null && (
                    <ButtonLink href={`/projects/${projectId}`} variant="primary">
                      Open the project
                    </ButtonLink>
                  )
                )}
                <Button variant="ghost" onClick={onEdit}>
                  Edit the brief
                </Button>
              </>
            )}
          </div>

          {failed && onRetry === null && projectId !== null && (
            <p className="mt-3 text-xs leading-relaxed text-ink-3">
              The project exists and holds whatever was written before it stopped. Carry on from
              inside the builder — retrying from here would be recorded as an edit to a
              half-finished site rather than a fresh first build.
            </p>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { Composer, type CreditContext } from "./Composer";
import { BuildLaunch } from "./BuildLaunch";
import {
  INITIAL_BUILD,
  parseStreamEvent,
  reduceBuild,
  type BuildProgress,
  type BuildSignal,
} from "./build-steps";

/** Same shape the homepage hand-off uses (lib/pending-prompt.ts) so a project
    started here is named the way a project started there is. Reimplemented
    rather than imported because that helper is not exported. */
function deriveName(prompt: string): string {
  const trimmed = prompt.trim().replace(/\s+/g, " ");
  return trimmed.length > 60 ? trimmed.slice(0, 57) + "…" : trimmed || "New site";
}

type Phase = "compose" | "building";

export function CreateFlow({
  initialPrompt,
  templateName,
  credits,
  billingHref,
}: {
  initialPrompt: string;
  templateName: string | null;
  credits: CreditContext;
  billingHref: string;
}) {
  const router = useRouter();
  const [phase, setPhase] = useState<Phase>("compose");
  const [prompt, setPrompt] = useState(initialPrompt);
  const [submitted, setSubmitted] = useState("");
  const [progress, setProgress] = useState<BuildProgress>(INITIAL_BUILD);
  const [projectId, setProjectId] = useState<string | null>(null);
  const [stopping, setStopping] = useState(false);
  /** True only when the server REFUSED the request with a non-2xx response.
      Those paths (kill switch, no credits, spend cap, rate limit) all return
      before app/api/generate/route.ts writes a Build row or a user Message, so
      the project is still pristine and a retry is genuinely a first build. */
  const [retrySafe, setRetrySafe] = useState(false);

  const abortRef = useRef<AbortController | null>(null);
  const stoppedRef = useRef(false);
  /** Mirrors `progress` for the async loop, which cannot read state. */
  const stateRef = useRef<BuildProgress>(INITIAL_BUILD);

  const running = phase === "building" && progress.outcome === "running";

  // Closing or reloading the tab drops the response body, which aborts the
  // model request server-side. Warning about it is the honest thing to do —
  // the alternative is someone losing a build they were watching.
  useEffect(() => {
    if (!running) return;
    const warn = (e: BeforeUnloadEvent) => e.preventDefault();
    window.addEventListener("beforeunload", warn);
    return () => window.removeEventListener("beforeunload", warn);
  }, [running]);

  const signal = useCallback((s: BuildSignal) => {
    const next = reduceBuild(stateRef.current, s);
    stateRef.current = next;
    setProgress(next);
    return next;
  }, []);

  const run = useCallback(
    async (text: string, image: string | null, existingProjectId: string | null) => {
      stateRef.current = INITIAL_BUILD;
      setProgress(INITIAL_BUILD);
      setStopping(false);
      setRetrySafe(false);
      stoppedRef.current = false;
      setSubmitted(text);
      setPhase("building");

      let id = existingProjectId;

      // ── 1. The project ───────────────────────────────────────────────────
      if (id === null) {
        try {
          const res = await fetch("/api/projects", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ name: deriveName(text) }),
          });
          const body: unknown = await res.json().catch(() => null);
          const created =
            typeof body === "object" && body !== null
              ? (body as { project?: { id?: unknown } }).project
              : undefined;
          if (!res.ok || typeof created?.id !== "string") {
            const message =
              typeof body === "object" && body !== null && typeof (body as { error?: unknown }).error === "string"
                ? (body as { error: string }).error
                : "Your project couldn't be created. Nothing was charged — try again.";
            signal({ kind: "failed", message });
            setRetrySafe(true);
            return;
          }
          id = created.id;
        } catch {
          signal({
            kind: "failed",
            message:
              "Your project couldn't be created — the request didn't reach Kodely. Nothing was charged.",
          });
          setRetrySafe(true);
          return;
        }
        setProjectId(id);
      }
      signal({ kind: "project-created" });

      // ── 2. The build ─────────────────────────────────────────────────────
      const controller = new AbortController();
      abortRef.current = controller;

      try {
        const res = await fetch("/api/generate", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ projectId: id, prompt: text, image }),
          signal: controller.signal,
        });

        if (!res.ok || !res.body) {
          const body: unknown = await res.json().catch(() => null);
          const message =
            typeof body === "object" && body !== null && typeof (body as { error?: unknown }).error === "string"
              ? (body as { error: string }).error
              : "The build couldn't be started.";
          // A refusal happens before anything is written or charged, so this
          // project is still a clean slate.
          setRetrySafe(true);
          signal({ kind: "failed", message });
          return;
        }

        signal({ kind: "accepted" });

        const reader = res.body.getReader();
        const decoder = new TextDecoder();
        let buffer = "";
        let sawTerminal = false;

        for (;;) {
          const { done, value } = await reader.read();
          if (done) break;
          buffer += decoder.decode(value, { stream: true });

          const frames = buffer.split("\n\n");
          buffer = frames.pop() ?? "";

          for (const frame of frames) {
            if (!frame.startsWith("data: ")) continue;
            let raw: unknown;
            try {
              raw = JSON.parse(frame.slice(6));
            } catch {
              continue;
            }
            const event = parseStreamEvent(raw);
            if (event === null) continue;
            if (event.type === "done" || event.type === "error") sawTerminal = true;
            signal({ kind: "sse", event });
          }
        }

        // The route always sends `done` or `error` unless the client went
        // away. A stream that ends without either IS a dropped connection —
        // saying "finished" here would be the exact lie this screen exists to
        // avoid.
        if (!sawTerminal) signal({ kind: "lost" });

        if (stateRef.current.outcome === "succeeded" && id !== null) {
          router.push(`/projects/${id}`);
        }
      } catch {
        if (stoppedRef.current) signal({ kind: "stopped" });
        else
          signal({
            kind: "failed",
            message:
              "The connection to the build dropped. Nothing was charged — open the project to see what was written.",
          });
      } finally {
        abortRef.current = null;
        setStopping(false);
      }
    },
    [router, signal],
  );

  function stop() {
    if (!running || stopping || abortRef.current === null) return;
    stoppedRef.current = true;
    setStopping(true);
    // A real cancel: aborting the fetch closes the response body, which fires
    // cancel() on the route's stream and aborts the model request. The Build
    // row is written FAILED with creditsCharged: 0.
    abortRef.current.abort();
  }

  if (phase === "building") {
    return (
      <BuildLaunch
        progress={progress}
        prompt={submitted}
        projectId={projectId}
        stopping={stopping}
        onStop={stop}
        onRetry={
          retrySafe && progress.outcome === "failed"
            ? () => void run(submitted, null, projectId)
            : null
        }
        onEdit={() => {
          setPhase("compose");
          setProgress(INITIAL_BUILD);
          stateRef.current = INITIAL_BUILD;
        }}
      />
    );
  }

  return (
    <Composer
      value={prompt}
      onChange={setPrompt}
      onSubmit={(text, image) => void run(text, image, projectId)}
      fromTemplate={templateName}
      credits={credits}
      billingHref={billingHref}
    />
  );
}

